import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half-cent ties to the even cent so invoices don't drift upward", () => {
    expect(roundCents(122.5)).toBe(122);
    expect(roundCents(123.5)).toBe(124);
    expect(roundCents(0.5)).toBe(0);
  });

  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(122.4)).toBe(122);
    expect(roundCents(122.6)).toBe(123);
    expect(roundCents(100)).toBe(100);
  });

  it("treats refunds (negative amounts) symmetrically", () => {
    expect(roundCents(-122.5)).toBe(-122);
    expect(roundCents(-123.5)).toBe(-124);
    expect(roundCents(-122.6)).toBe(-123);
  });
});

